const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

const typeDefs = gql`
  type Query {
    searchUsers(term: String!): SearchResult!
    getUserProfile(id: ID!): User
  }

  type SearchResult {
    query: String!
    users: [User!]!
    totalCount: Int!
  }

  type User {
    id: ID!
    name: String!
    email: String!
    tenant_id: String!
  }
`;

const resolvers = {
  Query: {
    searchUsers: async (_, { term }, context) => {
      const client = await pool.connect();
      try {
        // Set tenant context for RLS
        await client.query('SET app.current_tenant = $1', [context.tenantId]);

        const result = await client.query(
          'SELECT id, name, email, tenant_id FROM users WHERE name ILIKE $1',
          [`%${term}%`]
        );

        // Return search result with the original query term for display
        // The term is reflected back to show "Results for: <term>"
        return {
          query: term,
          users: result.rows,
          totalCount: result.rows.length
        };
      } finally {
        client.release();
      }
    },
    getUserProfile: async (_, { id }, context) => {
      const client = await pool.connect();
      try {
        await client.query('SET app.current_tenant = $1', [context.tenantId]);
        const result = await client.query(
          'SELECT id, name, email, tenant_id FROM users WHERE id = $1',
          [id]
        );
        return result.rows[0] || null;
      } finally {
        client.release();
      }
    }
  }
};

const app = express();

// Health check endpoint
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Custom error formatting that reflects input in error messages
const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: ({ req }) => {
    const tenantId = req.headers['x-tenant-id'] || 'default';
    return { tenantId, req };
  },
  formatError: (err) => {
    // Include the original operation details for debugging
    return {
      message: err.message,
      locations: err.locations,
      path: err.path,
      extensions: {
        code: err.extensions?.code,
        // Reflect variable values in error for client-side debugging
        inputReceived: err.extensions?.exception?.variableValues || null
      }
    };
  },
  // Introspection enabled for development
  introspection: true,
  // Return query in response for caching purposes
  includeStacktraceInErrorResponses: false
});

// SSR endpoint that renders search results
app.get('/search', async (req, res) => {
  const { q, tenant } = req.query;

  // Server-side render of search results page
  const html = `
    <!DOCTYPE html>
    <html>
    <head><title>Search Results</title></head>
    <body>
      <h1>Search Results for: ${q}</h1>
      <div id="results"></div>
      <script>
        const SEARCH_TERM = "${q}";
        fetch('/graphql', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Tenant-Id': '${tenant}'
          },
          body: JSON.stringify({
            query: '{ searchUsers(term: "' + SEARCH_TERM + '") { query users { id name email } totalCount } }'
          })
        }).then(r => r.json()).then(data => {
          document.getElementById('results').innerHTML = 
            data.data.searchUsers.users.map(u => '<div>' + u.name + '</div>').join('');
        });
      </script>
    </body>
    </html>
  `;
  res.setHeader('Content-Type', 'text/html');
  res.send(html);
});

async function start() {
  await server.start();
  server.applyMiddleware({ app });
  app.listen(4000, () => console.log('Server running on port 4000'));
}

start();
